from v2.models.knowledge_models import Topic


class NavigationEnricher:
    """
    Génère automatiquement :

    - prerequisites
    - next_topics
    - related_topics

    ainsi que les relations du Knowledge Graph.
    """

    def enrich(self, families):

        for family in families:

            for chapter in family.chapters:

                topics = sorted(
                    chapter.topics,
                    key=lambda topic: topic.editorial_order,
                )

                self._link_sequence(topics)
                self._link_related(topics)

        return families

    # ==========================================================
    # Navigation pédagogique
    # ==========================================================

    def _link_sequence(
        self,
        topics: list[Topic],
    ):

        for index, topic in enumerate(topics):

            # --------------------------------------------------

            if index > 0:

                previous = topics[index - 1]

                if previous.id not in topic.prerequisites:

                    topic.prerequisites.append(previous.id)

                topic.add_relation(
                    target=previous.id,
                    relation_type="prerequisite",
                    score=1.0,
                    source="NavigationEnricher",
                )

            # --------------------------------------------------

            if index < len(topics) - 1:

                nxt = topics[index + 1]

                if nxt.id not in topic.next_topics:

                    topic.next_topics.append(nxt.id)

                topic.add_relation(
                    target=nxt.id,
                    relation_type="next",
                    score=1.0,
                    source="NavigationEnricher",
                )

    # ==========================================================
    # Related
    # ==========================================================

    def _link_related(
        self,
        topics: list[Topic],
    ):

        for topic in topics:

            for other in topics:

                if other.id == topic.id:
                    continue

                if other.id not in topic.related_topics:

                    topic.related_topics.append(other.id)

                topic.add_relation(
                    target=other.id,
                    relation_type="related",
                    score=0.60,
                    source="NavigationEnricher",
                )

import json
import os
from typing import Type, TypeVar

from dotenv import load_dotenv
from openai import OpenAI
from pydantic import BaseModel, ValidationError

from .base import BaseLLM

load_dotenv()

T = TypeVar("T", bound=BaseModel)


class OpenAILLM(BaseLLM):
    """
    Implémentation OpenAI du moteur LLM.
    """

    def __init__(self):

        api_key = os.getenv("OPENAI_API_KEY")

        if not api_key:
            raise RuntimeError(
                "OPENAI_API_KEY introuvable dans le fichier .env."
            )

        self.client = OpenAI(
            api_key=api_key,
            timeout=60.0,
        )

    def generate(
        self,
        *,
        prompt: str,
        response_model: Type[T],
        temperature: float = 0.2,
    ) -> T:


        response = self.client.responses.create(

            model="gpt-5",
            input=prompt,

        )

        content = response.output_text.strip()

        # Gestion d'un éventuel bloc ```json
        if content.startswith("```"):
            content = content.replace("```json", "")
            content = content.replace("```", "")
            content = content.strip()

        try:
            data = json.loads(content)

        except json.JSONDecodeError as e:
            raise ValueError(
                f"Le modèle n'a pas renvoyé un JSON valide :\n\n{content}"
            ) from e

        try:
            return response_model.model_validate(data)

        except ValidationError as e:
            raise ValueError(
                f"Le JSON ne correspond pas au schéma {response_model.__name__}"
            ) from e

