    # ==========================================================
    # ASSURANCE-VIE — PAS D'EXONÉRATION SOUS 150 K€
    # ==========================================================

    def _validate_av_150k_not_exemption(
        self,
        content: str,
        rule: ProtectedRule,
    ) -> ProtectedRuleIssue | None:

        forbidden_patterns = (
            (
                r"(?:inferieur|en dessous|sous)"
                r".{0,80}150 000"
                r".{0,180}"
                r"(?:exonere|exoneration|aucun impot|non imposable)"
            ),
            (
                r"(?:exonere|exoneration|aucun impot|non imposable)"
                r".{0,180}"
                r"(?:inferieur|en dessous|sous)"
                r".{0,80}150 000"
            ),
        )

        if self._matches_any(
            content,
            forbidden_patterns,
        ):

            return self._issue(
                rule,
                (
                    "Le topic présente potentiellement le seuil "
                    "de 150 000 euros comme une exonération "
                    "générale d'impôt sur le revenu."
                ),
            )

        return None

    # ==========================================================
    # HELPERS
    # ==========================================================

    @staticmethod
    def _build_content(
        topic: WrittenTopic,
    ) -> str:

        return "\n".join(
            [
                topic.title,
                topic.summary,
                topic.description,
                *topic.keywords,
                *topic.vocabulary,
                *topic.examples,
                *topic.legal_sources,
            ]
        )

    @staticmethod
    def _normalize(
        value: str,
    ) -> str:
        """
        Normalise le contenu pour les contrôles déterministes.
        """

        value = value.lower()

        value = unicodedata.normalize(
            "NFKD",
            value,
        )

        value = "".join(
            character
            for character in value
            if not unicodedata.combining(character)
        )

        value = value.replace(
            "\u00a0",
            " ",
        )

        value = re.sub(
            r"\s+",
            " ",
            value,
        )

        return value.strip()

    @staticmethod
    def _matches_any(
        content: str,
        patterns: tuple[str, ...],
    ) -> bool:

        return any(
            re.search(
                pattern,
                content,
                flags=re.IGNORECASE | re.DOTALL,
            )
            for pattern in patterns
        )

